{"path": "grep.py", "content": "def grep(pattern, flags, files):
    flag_set = set(flags.split())
    line_numbers = "-n" in flag_set
    files_only = "-l" in flag_set
    ignore_case = "-i" in flag_set
    invert = "-v" in flag_set
    whole_line = "-x" in flag_set
    multiple = len(files) > 1

    needle = pattern.lower() if ignore_case else pattern

    def matches(line):
        text = line.rstrip("\n")
        if ignore_case:
            text = text.lower()
        found = text == needle if whole_line else needle in text
        return found != invert

    output = []
    for name in files:
        with open(name) as handle:
            lines = handle.readlines()
        for number, line in enumerate(lines, start=1):
            if not matches(line):
                continue
            if files_only:
                output.append(name + "\n")
                break
            prefix = ""
            if multiple:
                prefix += name + ":"
            if line_numbers:
                prefix += f"{number}:"
            if not line.endswith("\n"):
                line += "\n"
            output.append(prefix + line)
    return "".join(output)
"}

